Stap 1 – GW-staarten uit SEAS5-DCSM5 (R-chunk dir-es-seas5dcms5)
Uitvoer: &lt;station&gt;_stats_multi.pkl

statdata = {}
for station in stations:
    wl_dcsm = read_seas5_multi(station, paths.input_path)
    statdata[station] = fit_seas5_tails(
        wl_dcsm["wl"], wl_dcsm["dwind"], WL, bins, caseId=station
    )
    save_pkl(paths.out(f"{station}_stats_multi.pkl"), **statdata[station])
    print(f"{station}: GW-fit SEAS5-DCSM5 klaar")

Weibull-refit en tabellen (R-chunks wblfit en wblfit30)

for dirbins, ptab in [("22h", ptab22), ("30", ptab30)]:
    for station in stations:
        f = paths.out(f"{station}_stats_multi_meas3.pkl")
        if not f.exists():
            print(
                f"{station}: {f.name} niet gevonden, overgeslagen (voer eerst notebook 3 of 4 uit)"
            )
            continue
        weibull_refit_wl(station, load_pkl(f), FREQ, pbins, ptab, dirbins, paths, SLR)
        print(f"{station}: waterstandstabellen {dirbins} graden klaar")
